import { createTestContext } from '../../../../test-utils'
import { Diagnostic, path } from '@servicenow/sdk-build-core'

describe('WaitForADuration Diagnostics', () => {
    const ctx = createTestContext({ rootDir: path.resolve(__dirname, 'project') })
    beforeAll(() => ctx.initialize())
    afterEach(() => ctx.cleanup())
    describe('WaitForADuration - Argument Count Validation', () => {
        test('should error with 0 arguments', async () => {
            const project = ctx.createProject()
            const file = project.addFile({
                path: 'waitfor-0-args.now.ts',
                content: `
import '@servicenow/sdk/global'
import { Flow, wfa } from '@servicenow/sdk/automation'

Flow(
    {
        $id: Now.ID['test_flow'],
        name: 'Test Flow',
    },
    undefined,
    () => {
        // Invalid: no arguments
        wfa.flowLogic.waitForADuration()
    }
)
                `,
            })

            const diagnostics = await file.getDiagnostics()
            const error = diagnostics.find(
                (d) => d.message.includes('argument') && d.message.includes('waitForADuration')
            )
            expect(error).toBeDefined()
            expect(error?.level).toBe(Diagnostic.Level.Error)
        })

        test('should error with 2 arguments', async () => {
            const project = ctx.createProject()
            const file = project.addFile({
                path: 'waitfor-2-args.now.ts',
                content: `
import '@servicenow/sdk/global'
import { Flow, wfa } from '@servicenow/sdk/automation'

Flow(
    {
        $id: Now.ID['test_flow'],
        name: 'Test Flow',
    },
    undefined,
    () => {
        // Invalid: 2 arguments
        wfa.flowLogic.waitForADuration(
            {
                $id: Now.ID['wait'],
                durationType: 'explicit_duration',
                duration: '1 hour'
            },
            'extra_arg' as any
        )
    }
)
                `,
            })

            const diagnostics = await file.getDiagnostics()
            const error = diagnostics.find(
                (d) => d.message.includes('argument') && d.message.includes('waitForADuration')
            )
            expect(error).toBeDefined()
            expect(error?.level).toBe(Diagnostic.Level.Error)
        })

        test('should NOT error with 1 argument', async () => {
            const project = ctx.createProject()
            const file = project.addFile({
                path: 'waitfor-1-arg.now.ts',
                content: `
import '@servicenow/sdk/global'
import { Flow, wfa } from '@servicenow/sdk/automation'

Flow(
    {
        $id: Now.ID['test_flow'],
        name: 'Test Flow',
    },
    undefined,
    () => {
        // Valid: 1 argument
        wfa.flowLogic.waitForADuration({
            $id: Now.ID['wait'],
            durationType: 'explicit_duration',
            duration: '1 hour'
        })
    }
)
                `,
            })

            const diagnostics = await file.getDiagnostics()
            const error = diagnostics.find((d) => d.message.includes('argument') && d.message.includes('Expected'))
            expect(error).toBeUndefined()
        })
    })
})
